final_sql:
SELECT scheduled_headcount
FROM staffing_plans
WHERE site_id = 'ohare' AND role_id = 'fulfillment_associate';

SELECT COUNT(DISTINCT planning_date)
FROM daily_capacity_results
WHERE site_id = 'kenosha' AND service_target_met = 0;

SELECT COUNT(*) - COUNT(source_date) AS days_with_no_records
FROM (
    SELECT DISTINCT planning_date
    FROM modeled_daily_workload
) AS all_days
LEFT JOIN workload_daily_source ON all_days.planning_date = workload_daily_source.source_date;

SELECT median_hourly_wage
FROM staffing_plans
WHERE site_id = 'kenosha' AND role_id = 'packing_associate';

SELECT productivity_case, AVG(role_site_day_service_rate) as average_on_time_rate
FROM planning_run_summary
GROUP BY productivity_case;

SELECT SUM(capacity_gap_hours) / AVG(paid_hours_per_person) as estimated_additional_headcount
FROM daily_capacity_results dcr
JOIN staffing_plans sp ON dcr.run_id = sp.run_id AND dcr.site_id = sp.site_id AND dcr.role_id = sp.role_id;
